/** A decoded JSON object. */
export type Json = Record<string, unknown>;

/** Where Wing sends the payer after paying (`integration_type`). */
export const IntegrationType = {
  /** back to `return_url` in the browser (Wing's default) */
  webApp: 'WEBAPP',
  /** back into your app through the deep link you registered with Wing */
  mobileApp: 'MOBAPP',
} as const;
/** `WEBAPP` or `MOBAPP` */
export type IntegrationType =
  (typeof IntegrationType)[keyof typeof IntegrationType];

/**
 * Payment to authorize. `rand_str` and `timestamp` are generated by the
 * SDK; every optional field is sent only when set.
 */
export interface Payment {
  /** your unique order id (`order_reference_no`) */
  orderReferenceNo: string;
  /** amount to pay, at most 2 decimals; sent as `15.00` */
  amount: number;
  /** Wing redirects the payer here (GET) after paying, with `?status=success&token=...` */
  returnUrl: string;
  /** Wing redirects the payer here (GET) when they cancel */
  cancelUrl: string;
  /** `WEBAPP` (default) or `MOBAPP` for the deep link back to your app */
  integrationType?: IntegrationType | undefined;
  /** whether the Wing Bank app is on the payer's phone (`is_wingapp_installed`) */
  isWingAppInstalled?: boolean | undefined;
  /** remark of the product or item, max 255 characters */
  itemName?: string | undefined;
  /** name shown to the payer; Wing shows your registered name without it */
  merchantName?: string | undefined;
  /** Wing account filled in for the payer */
  wingAccount?: string | undefined;
}

/** `errorCode` and `errorText` of Wing responses. Success is `200`. */
export interface WingStatus {
  /** Wing's code, e.g. `200`, `401` (invalid REST API key), `006035` (not found) */
  code: string;
  /** human readable message */
  message: string;
}

/**
 * A Wing payment, as returned by the inquiry API and pushed to your
 * callback URL. Wing asks partners to accept only payments whose `amount`
 * is at least the price: check {@link covers} before delivering.
 */
export interface Transaction {
  /** amount the partner requested */
  amount: number;
  /** your `order_reference_no` */
  orderReferenceNo: string;
  /** Wing transaction id; show it on your success page */
  transactionId: string;
  /** total amount, which can include a fee or an exchange rate */
  totalAmount: number | undefined;
  currency: string | undefined;
  remark: string | undefined;
  customerName: string | undefined;
  fee: number | undefined;
  feeCurrency: string | undefined;
  wingAccount: string | undefined;
  psTrnId: string | undefined;
  fcTrnId: string | undefined;
  billerName: string | undefined;
  /** as Wing sends it, e.g. `28-08-23 09:34:38` */
  transactionDate: string | undefined;
  /** every field Wing sent, including ones this type does not model */
  raw: Json;
  /** whether `amount` is at least `price`, compared in cents */
  covers(price: number): boolean;
}

/** Response of the authorization API. */
export interface AuthorizationResponse {
  status: WingStatus;
  /** authorization token (a JWT), on success */
  token: string | undefined;
  /** Wing's payment page for `token`: redirect the payer there */
  confirmUrl: string | undefined;
  /** whether Wing authorized the payment */
  isSuccess: boolean;
}

/** Response of the transaction inquiry API. */
export interface InquiryResponse {
  status: WingStatus;
  /** the transaction, when `isSuccess` */
  transaction: Transaction | undefined;
  /** whether Wing found the transaction */
  isSuccess: boolean;
  /** whether the transaction was found and its amount is at least `price` */
  isPaid(price: number): boolean;
}

// ---- lenient readers: strings and numbers whatever type Wing sends -------

function optionalString(json: Json, key: string): string | undefined {
  const value = json[key];
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }
  return undefined;
}

function optionalNumber(json: Json, key: string): number | undefined {
  const value = json[key];
  const number =
    typeof value === 'number'
      ? value
      : typeof value === 'string' && value.trim() !== ''
        ? Number(value)
        : NaN;
  return Number.isFinite(number) ? number : undefined;
}

const isObject = (value: unknown): value is Json =>
  value !== null && typeof value === 'object' && !Array.isArray(value);

/** Parses Wing's `errorCode` / `errorText`. */
export function statusFromJson(json: Json): WingStatus {
  return {
    code: optionalString(json, 'errorCode') ?? '',
    message: optionalString(json, 'errorText') ?? '',
  };
}

/** Parses a transaction of the inquiry API or the callback. */
export function transactionFromJson(json: Json): Transaction {
  const amount = optionalNumber(json, 'amount') ?? 0;
  return {
    amount,
    orderReferenceNo: optionalString(json, 'order_reference_no') ?? '',
    transactionId: optionalString(json, 'transaction_id') ?? '',
    totalAmount: optionalNumber(json, 'total_amount'),
    currency: optionalString(json, 'currency'),
    remark: optionalString(json, 'remark'),
    customerName: optionalString(json, 'customer_name'),
    fee: optionalNumber(json, 'fee'),
    feeCurrency: optionalString(json, 'fee_currency'),
    wingAccount: optionalString(json, 'wing_account'),
    psTrnId: optionalString(json, 'ps_trn_id'),
    fcTrnId: optionalString(json, 'fc_trn_id'),
    billerName: optionalString(json, 'biller_name'),
    transactionDate: optionalString(json, 'transaction_date'),
    raw: json,
    covers: (price) => Math.round(amount * 100) >= Math.round(price * 100),
  };
}

/** Parses the inquiry response: the transaction is at the top level, or inside `data`. */
export function inquiryResponseFromJson(json: Json): InquiryResponse {
  const status = statusFromJson(json);
  const data = json['data'];
  const transaction =
    status.code === '200'
      ? transactionFromJson(isObject(data) ? data : json)
      : undefined;
  return {
    status,
    transaction,
    isSuccess: transaction !== undefined,
    isPaid: (price) => transaction?.covers(price) ?? false,
  };
}
